def transform(g):
 h=len(g); w=len(g[0]); bg=max(set(x for row in g for x in row),key=lambda x:sum(r.count(x) for r in g))
 pts={}
 for r in range(h):
  for c in range(w):
   if g[r][c]!=bg: pts.setdefault(g[r][c],[]).append((r,c))
 out=[row[:] for row in g]
 # For colors occurring at least twice, extrapolate pairwise straight diagonal/horizontal/vertical line from each pair in both directions.
 for color,ps in pts.items():
  for i,(r,c) in enumerate(ps):
   for rr,cc in ps[i+1:]:
    dr=rr-r; dc=cc-c
    if not (dr==0 or dc==0 or abs(dr)==abs(dc)): continue
    import math
    k=math.gcd(abs(dr),abs(dc)); sr=dr//k; sc=dc//k
    # only extend if distance one step (pair adjacent)
    if k!=1: continue
    for sign in (-1,1):
     y,x=r-sign*sr,c-sign*sc
     while 0<=y<h and 0<=x<w:
      if out[y][x]==bg: out[y][x]=color
      y-=sign*sr; x-=sign*sc
 return out

